// Work out where this conversation stands before the AI is allowed near it.
// Three things decide that: have we already handled this exact message, is the
// 24 hour customer service window still open, and what did we say last time.

const msg = $('Message arrives on WhatsApp').first().json;

const entry   = msg.messages && msg.messages[0] ? msg.messages[0] : {};
const contact = msg.contacts && msg.contacts[0] ? msg.contacts[0] : {};

const waId      = contact.wa_id || entry.from || '';
const messageId = entry.id || '';
const text      = (entry.text && entry.text.body) || '';
const sentAtSec = Number(entry.timestamp || 0);

// Rows already in the Conversations tab, newest first.
const rows = $('Conversation so far').all()
  .map(i => i.json)
  .filter(r => String(r.wa_id || '') === String(waId));

const prior = rows.length ? rows[rows.length - 1] : null;

// 1. Duplicate delivery. Meta retries a webhook when it does not get a 200
//    quickly enough, so the same message id can arrive more than once. Answering
//    twice is worse than answering late.
const alreadyHandled = !!prior && String(prior.last_message_id || '') === String(messageId) && messageId !== '';

// 2. The 24 hour window. Meta measures it from the customer's LAST message,
//    and the message being handled right now IS a customer message, so the
//    window is open unless this webhook itself arrived more than a day late.
//    Measuring from the previous message instead sent a template to people
//    who had just written in.
const lastInboundMs = sentAtSec ? sentAtSec * 1000 : Date.now();
const hoursSinceInbound = (Date.now() - lastInboundMs) / 3600000;
const windowOpen = hoursSinceInbound < 24;

// 3. Never let the agent reply to someone a human has taken over, and never let
//    it argue with a complaint.
const handedOver = !!prior && String(prior.stage || '') === 'handoff';

const COMPLAINT_WORDS = ['complaint', 'complain', 'refund', 'lawyer', 'legal',
  'scam', 'fraud', 'terrible', 'worst', 'sue'];
// Whole words only. A substring match sent "no issue, just asking" to a
// person because "issue" contains "sue".
const looksLikeComplaint = COMPLAINT_WORDS.some(w => new RegExp('\\b' + w + '\\b', 'i').test(text));

const turns = prior && prior.turns ? String(prior.turns) : '';

return [{
  json: {
    wa_id: waId,
    message_id: messageId,
    text,
    name: contact.profile && contact.profile.name ? contact.profile.name : '',
    already_handled: alreadyHandled,
    window_open: windowOpen,
    handed_over: handedOver,
    looks_like_complaint: looksLikeComplaint,
    needs_human_now: handedOver || looksLikeComplaint,
    hours_since_inbound: Math.round(hoursSinceInbound * 10) / 10,
    last_inbound_at: new Date(lastInboundMs).toISOString(),
    turns,
    stage: prior ? prior.stage || 'new' : 'new',
    collected: prior && prior.collected ? prior.collected : '',
  },
}];

// The agent has answered. Decide what actually happens, and record it.
// The agent is allowed to draft. It is not allowed to decide on its own that a
// lead is hot, or to send anything outside the 24 hour window.

const state = $('Work out where this conversation stands').first().json;

let ai = $json.output;
if (typeof ai === 'string') {
  try { ai = JSON.parse(ai); } catch (e) { ai = { reply: ai }; }
}
ai = ai || {};

const score = Number(ai.lead_score);
const leadScore = Number.isFinite(score) ? Math.max(0, Math.min(10, score)) : 0;

// Tunables
const HOT_SCORE       = 7;   // at or above this, sales is told straight away
const MIN_REPLY_CHARS = 2;   // an empty draft is a failure, not a reply

// What we know is the sum of every turn, not only this one. The previous
// turns are stored on the row as JSON; this turn's answers are laid on top,
// and a blank never overwrites something already known.
let priorCollected = {};
try { priorCollected = state.collected ? JSON.parse(state.collected) : {}; } catch (e) { priorCollected = {}; }
if (!priorCollected || typeof priorCollected !== 'object' || Array.isArray(priorCollected)) priorCollected = {};
const fresh = (ai.collected && typeof ai.collected === 'object' && !Array.isArray(ai.collected)) ? ai.collected : {};
const collected = Object.assign({}, priorCollected);
for (const k of Object.keys(fresh)) {
  const v = fresh[k];
  if (v !== null && v !== undefined && String(v).trim() !== '') collected[k] = v;
}
const haveName    = !!(collected.name || state.name);
const haveService = !!collected.service;
const haveBudget  = !!collected.budget;
const qualified   = haveName && haveService && (haveBudget || leadScore >= HOT_SCORE);

const draft = String(ai.reply || '').trim();
const draftUsable = draft.length >= MIN_REPLY_CHARS;

// A human takes it when the agent asks for one, when the message reads as a
// complaint, when a human already took it, or when the agent produced nothing.
const toHuman = state.needs_human_now || ai.needs_human === true || !draftUsable;

let route;
if (toHuman)                route = 'human';
else if (!state.window_open) route = 'template';
else                         route = 'reply';

// 'booked' is the word the hourly lane checks. Writing 'booking' here meant a
// lead who asked to meet was nudged anyway.
const stage = toHuman ? 'handoff'
  : (ai.booking_requested ? 'booked' : 'awaiting_reply');

const reason = state.handed_over ? 'a person already took this conversation'
  : state.looks_like_complaint ? 'the message reads as a complaint'
  : !draftUsable ? 'the agent produced no usable reply'
  : ai.needs_human === true ? 'the agent asked for a person'
  : !state.window_open ? 'the 24 hour window has closed, so only a template may be sent'
  : 'handled by the agent';

return [{
  json: {
    wa_id: state.wa_id,
    name: collected.name || state.name || '',
    text_in: state.text,
    reply: draft,
    route,
    stage,
    reason,
    lead_score: leadScore,
    qualified,
    language: ai.language || 'en',
    intent: ai.intent || '',
    collected: JSON.stringify(collected),
    hot: qualified && leadScore >= HOT_SCORE,
    last_message_id: state.message_id,
    last_inbound_at: state.last_inbound_at,
    followup_sent: '',   // a new message starts a new lull, so one nudge is allowed again
    handled_at: new Date().toISOString(),
  },
}];

