// Hourly: find conversations that went quiet and decide whether a nudge is
// allowed. The rule that matters is Meta's, not ours: after 24 hours only an
// approved template may be sent, and nobody gets nudged twice.

const rows = $('All conversations').all().map(i => i.json);

const QUIET_AFTER_HOURS = 4;    // long enough that they are not still typing
const GIVE_UP_AFTER_DAYS = 7;   // past this, stop

const out = [];
for (const r of rows) {
  const wa_id = String(r.wa_id || '');
  if (!wa_id) continue;

  const lastIn = Date.parse(r.last_inbound_at || '');
  if (!Number.isFinite(lastIn)) continue;

  const hours = (Date.now() - lastIn) / 3600000;
  const stage = String(r.stage || '');
  const nudged = String(r.followup_sent || '').toLowerCase() === 'true';

  let action = 'skip';
  let reason = '';

  if (stage === 'handoff')            reason = 'a person has it';
  else if (stage === 'booked' || stage === 'booking') reason = 'already booked';   // 'booking' is what an earlier version wrote
  else if (nudged)                    reason = 'already nudged once';
  else if (hours < QUIET_AFTER_HOURS) reason = 'not quiet yet';
  else if (hours > GIVE_UP_AFTER_DAYS * 24) reason = 'too old';
  else if (hours < 24) { action = 'freeform_nudge'; reason = 'inside the 24 hour window'; }
  else                 { action = 'template';       reason = 'outside the 24 hour window, template only'; }

  out.push({ json: {
    wa_id,
    name: r.name || '',
    action,
    reason,
    hours_since_inbound: Math.round(hours * 10) / 10,
    lead_score: Number(r.lead_score || 0),
  }});
}

// Quietest first, so the oldest lead is not the one that gets dropped.
out.sort((a, b) => b.json.hours_since_inbound - a.json.hours_since_inbound);
return out;

